A, B = {1, 2, 3, 4}, {3, 4, 5}
print(A | B, A & B, A - B, A ^ B)        # union, intersection, difference, symmetric difference
print(A <= {1, 2, 3, 4, 5}, 3 in A)      # subset, membership

zero = frozenset()                       # von Neumann's numbers: 0 = {}, n + 1 = n U {n}
def successor(n): return n | frozenset([n])
one, two, three = successor(zero), successor(successor(zero)), successor(successor(successor(zero)))
print(len(zero), len(one), len(two), len(three))     # 0 1 2 3: each number is the set of the ones before it

print([2 ** n for n in range(6)])        # a set of n items has 2**n subsets: always more than n

def R(s):                       # R(s) means: "s does not contain itself"
    return not s(s)

try:
    print(R(R))                 # does R contain itself? it never settles
except RecursionError:
    print("R(R) never settles: if it is True it must be False, and vice versa")

is_heap = lambda grains: grains >= 1_000        # any sharp cutoff feels arbitrary
print(is_heap(1000), is_heap(999))               # one grain flips the verdict

class Stack:                        # the interface: push, pop. How it stores things is hidden.
    def __init__(self):
        self._items = []
    def push(self, x): self._items.append(x)
    def pop(self): return self._items.pop()

class LinkedStack:                  # a different implementation behind the same interface
    def __init__(self):
        self._head = None
    def push(self, x): self._head = (x, self._head)
    def pop(self):
        x, self._head = self._head
        return x

def reverse(words, stack):          # this code depends only on the abstraction
    for w in words: stack.push(w)
    return [stack.pop() for _ in words]

print(reverse("one two three".split(), Stack()), reverse("one two three".split(), LinkedStack()))
